use crate::diagnostics::{contracts::{DiagnosticExportRequest,DiagnosticExportResult},errors::DiagnosticError,powershell::run,redaction::redact_json};
use chrono::Utc;use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs::{self,File},io::{Read,Write},path::{Path,PathBuf}};use tauri::{AppHandle,Manager};use uuid::Uuid;use zip::{write::SimpleFileOptions,CompressionMethod,ZipWriter};
fn export_root(app:&AppHandle)->Result<PathBuf,DiagnosticError>{let root=app.path().app_data_dir().map_err(|e|DiagnosticError::Export(e.to_string()))?.join("diagnostics").join("exports");fs::create_dir_all(&root).map_err(|e|DiagnosticError::Filesystem(e.to_string()))?;Ok(root)}
fn sha256_file(path:&Path)->Result<String,DiagnosticError>{let mut file=File::open(path).map_err(|e|DiagnosticError::Filesystem(e.to_string()))?;let mut hasher=Sha256::new();let mut buffer=[0u8;1024*1024];loop{let count=file.read(&mut buffer).map_err(|e|DiagnosticError::Filesystem(e.to_string()))?;if count==0{break;}hasher.update(&buffer[..count]);}Ok(hex::encode(hasher.finalize()))}
fn system_summary()->Value{let script=r#"$os=Get-CimInstance Win32_OperatingSystem;$cs=Get-CimInstance Win32_ComputerSystem;$cpu=Get-CimInstance Win32_Processor|Select-Object -First 1;[pscustomobject]@{computerName=$env:COMPUTERNAME;os=[string]$os.Caption;build=[string]$os.BuildNumber;architecture=[string]$os.OSArchitecture;cpu=[string]$cpu.Name;ramBytes=[uint64]$cs.TotalPhysicalMemory;capturedAt=(Get-Date).ToUniversalTime().ToString('o')}|ConvertTo-Json -Compress"#;run(script).ok().and_then(|o|serde_json::from_str(&o.stdout).ok()).unwrap_or_else(||json!({"unavailable":true}))}
fn markdown(title:&str,evidence:&Value)->String{format!("# {}\n\nGenerated: {}\n\n```json\n{}\n```\n",title,Utc::now().to_rfc3339(),serde_json::to_string_pretty(evidence).unwrap_or_default())}fn escape(v:&str)->String{v.replace('&',"&amp;").replace('<',"&lt;").replace('>',"&gt;").replace('"',"&quot;")}fn html(title:&str,evidence:&Value)->String{format!("<!doctype html><meta charset=\"utf-8\"><title>{}</title><style>body{{font-family:Segoe UI,Arial;background:#08111f;color:#e6edf7;padding:32px}}pre{{white-space:pre-wrap;background:#101d31;padding:20px;border-radius:12px}}</style><h1>{}</h1><p>{}</p><pre>{}</pre>",escape(title),escape(title),Utc::now().to_rfc3339(),escape(&serde_json::to_string_pretty(evidence).unwrap_or_default()))}
pub fn report(app:&AppHandle,request:&DiagnosticExportRequest)->Result<DiagnosticExportResult,DiagnosticError>{let export_id=Uuid::new_v4().to_string();let format=request.format.to_lowercase();if !["json","markdown","html"].contains(&format.as_str()){return Err(DiagnosticError::InvalidRequest("report format must be json, markdown, or html".into()));}let(evidence,redaction_count)=if request.redact{redact_json(&request.evidence)}else{(request.evidence.clone(),0)};let mut payload=json!({"title":request.title,"createdAt":Utc::now().to_rfc3339(),"evidence":evidence,"redacted":request.redact});if request.include_system_summary{payload["systemSummary"]=system_summary();}let extension=if format=="markdown"{"md"}else{format.as_str()};let path=export_root(app)?.join(format!("diagnostic-report-{export_id}.{extension}"));let body=match format.as_str(){"json"=>serde_json::to_string_pretty(&payload).unwrap_or_default(),"markdown"=>markdown(&request.title,&payload),"html"=>html(&request.title,&payload),_=>unreachable!()};fs::write(&path,body.as_bytes()).map_err(|e|DiagnosticError::Export(e.to_string()))?;let size_bytes=fs::metadata(&path).map_err(|e|DiagnosticError::Filesystem(e.to_string()))?.len();if size_bytes==0{return Err(DiagnosticError::Export("exported report is empty".into()));}Ok(DiagnosticExportResult{export_id,path:path.to_string_lossy().to_string(),format,size_bytes,created_at:Utc::now().to_rfc3339(),redaction_count,sha256:sha256_file(&path)?,included_files:vec![path.file_name().unwrap_or_default().to_string_lossy().to_string()],warnings:Vec::new()})}
pub fn bundle(app:&AppHandle,request:&DiagnosticExportRequest)->Result<DiagnosticExportResult,DiagnosticError>{let export_id=Uuid::new_v4().to_string();let root=export_root(app)?;let staging=root.join(format!("bundle-{export_id}"));fs::create_dir_all(&staging).map_err(|e|DiagnosticError::Filesystem(e.to_string()))?;let(evidence,redaction_count)=if request.redact{redact_json(&request.evidence)}else{(request.evidence.clone(),0)};let evidence_path=staging.join("evidence.json");fs::write(&evidence_path,serde_json::to_vec_pretty(&evidence).unwrap_or_default()).map_err(|e|DiagnosticError::Export(e.to_string()))?;let mut included=vec!["evidence.json".to_string()];if request.include_system_summary{let p=staging.join("system-summary.json");fs::write(&p,serde_json::to_vec_pretty(&system_summary()).unwrap_or_default()).map_err(|e|DiagnosticError::Export(e.to_string()))?;included.push("system-summary.json".into());}let manifest=json!({"title":request.title,"bundleId":export_id,"createdAt":Utc::now().to_rfc3339(),"redacted":request.redact,"redactionCount":redaction_count,"files":included});fs::write(staging.join("manifest.json"),serde_json::to_vec_pretty(&manifest).unwrap_or_default()).map_err(|e|DiagnosticError::Export(e.to_string()))?;included.push("manifest.json".into());let zip_path=root.join(format!("diagnostic-support-{export_id}.zip"));let file=File::create(&zip_path).map_err(|e|DiagnosticError::Export(e.to_string()))?;let mut zip=ZipWriter::new(file);let options=SimpleFileOptions::default().compression_method(CompressionMethod::Deflated).unix_permissions(0o600);for name in &included{let bytes=fs::read(staging.join(name)).map_err(|e|DiagnosticError::Filesystem(e.to_string()))?;zip.start_file(name,options).map_err(|e|DiagnosticError::Export(e.to_string()))?;zip.write_all(&bytes).map_err(|e|DiagnosticError::Export(e.to_string()))?;}zip.finish().map_err(|e|DiagnosticError::Export(e.to_string()))?;let _=fs::remove_dir_all(&staging);let size_bytes=fs::metadata(&zip_path).map_err(|e|DiagnosticError::Filesystem(e.to_string()))?.len();if size_bytes==0{return Err(DiagnosticError::Export("support bundle is empty".into()));}Ok(DiagnosticExportResult{export_id,path:zip_path.to_string_lossy().to_string(),format:"zip".into(),size_bytes,created_at:Utc::now().to_rfc3339(),redaction_count,sha256:sha256_file(&zip_path)?,included_files:included,warnings:vec!["Support bundle is stored locally and is not uploaded automatically.".into()]})}
